@MainActor
final class PlayerController {
    let player = AVPlayer()
    private var observations: [NSKeyValueObservation] = []

    func load(_ url: URL, resumeAt: CMTime) {
        let item = AVPlayerItem(url: url)
        item.preferredForwardBufferDuration = 5
        player.replaceCurrentItem(with: item)
        observations = [
            player.observe(\.timeControlStatus) { p, _ in
                MainActor.assumeIsolated { self.report(p.timeControlStatus) }
            }
        ]
        player.seek(to: resumeAt)
        player.play()
    }
    private func report(_ s: AVPlayer.TimeControlStatus) { /* buffering vs playing metrics */ }
}
